// Normalize Reddit RSS feed to the standard article structure
const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;
  const title = j.title || '';
  const link = j.link || j.guid || '';
  if (!title || !link) continue;

  const lowerTitle = title.toLowerCase();
  if (lowerTitle.indexOf('free talk friday') !== -1) continue;
  if (lowerTitle.indexOf('daily thread') !== -1) continue;
  if (lowerTitle.indexOf('game thread') !== -1) continue;

  let date = '';
  if (j.isoDate) date = new Date(j.isoDate).toISOString().split('T')[0];
  else if (j.pubDate) date = new Date(j.pubDate).toISOString().split('T')[0];

  let description = j.contentSnippet || '';
  if (!description && j.content) {
    description = j.content.replace(/<[^>]*>/g, ' ');
  }
  description = description
    .replace(/submitted by[\s\S]*$/i, '')
    .replace(/\[link\]\s*\[comments\]/gi, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 300);

  results.push({ json: { title: title, date: date, link: link, source: 'Reddit', score: 0, description: description } });
}

return results.length > 0 ? results : [{ json: { empty: true, source: 'Reddit' } }];

// Normalize Google News RSS items to the standard structure
const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;
  const link = j.link || j.url || j.guid || '';
  if (!j.title || !link) continue;
  let date = '';
  if (j.pubDate) date = new Date(j.pubDate).toISOString().split('T')[0];
  else if (j.isoDate) date = new Date(j.isoDate).toISOString().split('T')[0];
  let description = (j.description || j.content || j.contentSnippet || '')
    .replace(/<[^>]*>/g, '').substring(0, 300);
  results.push({ json: { title: j.title, date: date, link: link, source: 'Google News', score: 0, description: description } });
}

return results.length > 0 ? results : [{ json: { empty: true, source: 'Google News' } }];

const xml = $input.first().json.data;

const items = [];
const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
const titleRegex = /<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([\s\S]*?)<\/title>/i;
const linkRegex = /<link>([\s\S]*?)<\/link>/i;
const descRegex = /<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>|<description>([\s\S]*?)<\/description>/i;
const pubDateRegex = /<pubDate>([\s\S]*?)<\/pubDate>/i;

let match;
while ((match = itemRegex.exec(xml)) !== null) {
  const itemXml = match[1];
  const titleMatch = titleRegex.exec(itemXml);
  const linkMatch = linkRegex.exec(itemXml);
  const descMatch = descRegex.exec(itemXml);
  const pubDateMatch = pubDateRegex.exec(itemXml);

  const title = (titleMatch && (titleMatch[1] || titleMatch[2]) || '').trim();
  const link = (linkMatch && linkMatch[1] || '').trim();
  if (!title || !link) continue;
  let date = '';
  const pd = (pubDateMatch && pubDateMatch[1] || '').trim();
  if (pd) { const d = new Date(pd); if (!isNaN(d)) date = d.toISOString().split('T')[0]; }

  items.push({ json: {
    title: title,
    date: date,
    link: link,
    source: 'Yahoo Sports News',
    score: 0,
    description: (descMatch && (descMatch[1] || descMatch[2]) || '').replace(/<[^>]+>/g, '').trim().substring(0, 300)
  } });
}

return items.length > 0 ? items : [{ json: { empty: true, source: 'Yahoo Sports News' } }];

