// Randomly select N articles (N from WordPress config) with representation from all sources
// ONLY include articles from the last 10 days
const items = $input.all();
const cfg = $('Set — Newsletter Config').first().json;
const topic = (cfg.topic || '').toLowerCase();
const targetCount = parseInt(cfg.article_count, 10) || 7;
const seen = new Set();

const now = new Date();
const cutoffDate = new Date(now.getTime() - (10 * 24 * 60 * 60 * 1000));
const cutoffStr = cutoffDate.toISOString().split('T')[0];

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const sources = ['Reddit', 'Google News', 'Yahoo Sports News', 'NCAA.com', 'BBC Sports'];
const bySource = {};
for (const s of sources) bySource[s] = [];

for (const item of items) {
  const j = item.json;
  if (j.empty || !j.title || !j.link || seen.has(j.link)) continue;
  seen.add(j.link);
  if (j.date && j.date < cutoffStr) continue;
  const article = { title: j.title, date: j.date || '', link: j.link, source: j.source };
  if (bySource[j.source]) bySource[j.source].push(article);
}

const selected = [];
for (const s of sources) {
  const shuffled = shuffle(bySource[s]);
  if (shuffled.length > 0) selected.push(shuffled[0]);
  bySource[s] = shuffled.slice(1);
}

const pool = shuffle([].concat(...sources.map(s => bySource[s])));
while (selected.length < targetCount && pool.length > 0) selected.push(pool.shift());

return [{ json: {
  articles: shuffle(selected.slice(0, targetCount)),
  topic: topic,
  cutoffDate: cutoffStr,
  articlesSelected: Math.min(selected.length, targetCount)
} }];

